
import random

import numpy as np
import torch
import torch.nn.functional as F

from RL import ChessNet
from teacher_data import generate_teacher_dataset


# Trains the network using positions generated by the expert teacher.
def train_expert():

    device = torch.device(
        "cuda" if torch.cuda.is_available()
        else "cpu"
    )

    print("Device:", device)

    # Generate expert data
    dataset = generate_teacher_dataset(
        num_games=50,
        depth=3
    )

    print("Total training positions:", len(dataset))

    if len(dataset) < 2:
        raise RuntimeError("Not enough teacher data")

    # Create model
    model = ChessNet().to(device)

    # Continue from an existing model if available
    try:

        model.load_state_dict(
            torch.load(
                "chess_model.pth",
                map_location=device
            )
        )

        print("Loaded existing ChessNet weights")

    except FileNotFoundError:

        print("Starting with a new ChessNet")

    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=0.0005,
        weight_decay=0.0001
    )

    batch_size = 64
    epochs = 20

    model.train()

    for epoch in range(epochs):

        random.shuffle(dataset)

        total_loss = 0
        total_policy_loss = 0
        total_value_loss = 0

        steps = 0

        for start in range(
            0,
            len(dataset),
            batch_size
        ):

            batch = dataset[
                start:start + batch_size
            ]

            states = np.stack([
                item[0] for item in batch
            ])

            policies = np.stack([
                item[1] for item in batch
            ])

            values = np.array([
                item[2] for item in batch
            ], dtype=np.float32)

            states = torch.tensor(
                states,
                dtype=torch.float32,
                device=device
            )

            policies = torch.tensor(
                policies,
                dtype=torch.float32,
                device=device
            )

            values = torch.tensor(
                values,
                dtype=torch.float32,
                device=device
            ).view(-1, 1)

            # Forward pass
            predicted_policy, predicted_value = model(
                states
            )

            # Policy loss
            log_policy = F.log_softmax(
                predicted_policy,
                dim=1
            )

            policy_loss = -(
                policies * log_policy
            ).sum(dim=1).mean()

            # Value loss
            value_loss = F.mse_loss(
                predicted_value,
                values
            )

            # Combined loss
            loss = policy_loss + value_loss

            optimizer.zero_grad()

            loss.backward()

            torch.nn.utils.clip_grad_norm_(
                model.parameters(),
                1.0
            )

            optimizer.step()

            total_loss += loss.item()

            total_policy_loss += policy_loss.item()

            total_value_loss += value_loss.item()

            steps += 1

        print(
            f"Epoch {epoch + 1}/{epochs} "
            f"| Loss: {total_loss / steps:.4f} "
            f"| Policy: {total_policy_loss / steps:.4f} "
            f"| Value: {total_value_loss / steps:.4f}"
        )

        # Save after every epoch
        torch.save(
            model.state_dict(),
            "chess_model.pth"
        )

    print("Expert training complete!")

    return model


if __name__ == "__main__":
    train_expert()
